export interface Item { price: number; qty: number }

export function calcTotal(items: Item[], discount = 0): number {
  const sum = items.reduce((acc, i) => acc + i.price * i.qty, 0)
  return Math.round(sum * (1 - discount))
}

files.src/payment.ts:
import { calcTotal, Item } from './order'

const MAX_RETRY = 3

export async function charge(items: Item[], pay: (amount: number) => Promise<void>) {
  const amount = calcTotal(items, 0.1)
  for (let i = 0; i < MAX_RETRY; i++) {
    try { return await pay(amount) } catch { /* retry immediately */ }
  }
  throw new Error('payment failed')
}

